def experiment(inputs):
    import random
    params = inputs.get('parameters', {'feedback_intensity': 3.0})
    seeds = inputs.get('seeds', [13, 71, 43, 101])
    results = []
    for seed in seeds:
        rng = random.Random(seed)
        val = rng.gauss(0, 1)
        for _ in range(5):
            val = val + params['feedback_intensity'] * (val ** 3 - val)
        results.append(val)
    return {"measurements": {"distributional_spread": results}}
